// count_primes.c: count primes below N (default 1e9) with a multithreaded,
// cache-blocked, odd-only segmented sieve of Eratosthenes.
//
// Build: gcc -O3 -march=native -fopenmp count_primes.c -o count_primes
// Run:   ./count_primes [N]

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#ifdef _OPENMP
#include <omp.h>
#else
static int omp_get_num_threads(void) { return 1; }
static int omp_get_thread_num(void) { return 0; }
#endif

#define SEG (1u << 17) /* slots per segment: 128 KiB, sized to stay in L2 */

static double now(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main(int argc, char **argv) {
    uint64_t N = argc > 1 ? strtoull(argv[1], NULL, 10) : 1000000000ULL;
    if (N <= 2) {
        printf("0\n");
        return 0;
    }

    // Slot j stands for the odd value 2j+1. Odd values below N are slots [0, M).
    uint64_t M = N / 2;

    // Base primes: odd primes p with p*p < N, found with a small sieve.
    uint64_t lim = 1;
    while (lim * lim < N) lim++;
    unsigned char *small = calloc(lim + 1, 1); // 0 = prime candidate
    small[0] = small[1] = 1;
    for (uint64_t i = 2; i * i <= lim; i++)
        if (!small[i])
            for (uint64_t j = i * i; j <= lim; j += i) small[j] = 1;

    uint64_t *bp = malloc((lim + 1) * sizeof *bp);
    uint64_t nb = 0;
    for (uint64_t p = 3; p <= lim; p += 2)
        if (!small[p] && p * p < N) bp[nb++] = p;
    free(small);

    uint64_t K = (M + SEG - 1) / SEG; // number of segments
    double t0 = now();
    uint64_t total = 1; // the prime 2

    #pragma omp parallel reduction(+ : total)
    {
        int T = omp_get_num_threads();
        int t = omp_get_thread_num();

        // Each thread takes one contiguous run of segments, so it can keep
        // its per-prime "next composite" cursor across segments.
        uint64_t s0 = K * t / T, s1 = K * (t + 1) / T;
        unsigned char *seg = malloc(SEG);
        uint64_t *nxt = malloc((nb + 1) * sizeof *nxt);

        // Position each cursor at the first odd multiple of p that is >= p*p
        // and >= the value at slot lo0.
        uint64_t v = 2 * (s0 * SEG) + 1;
        for (uint64_t i = 0; i < nb; i++) {
            uint64_t p = bp[i], pp = p * p;
            uint64_t s = (v + p - 1) / p * p;
            if (s < pp) s = pp;
            if (!(s & 1)) s += p; // p is odd, so this makes s odd
            nxt[i] = (s - 1) / 2;
        }

        for (uint64_t k = s0; k < s1; k++) {
            uint64_t lo = k * SEG;
            uint64_t hi = lo + SEG < M ? lo + SEG : M;
            uint64_t len = hi - lo;

            memset(seg, 1, len);
            if (lo == 0) seg[0] = 0; // the value 1 is not prime

            // Consecutive odd multiples of p differ by 2p in value, i.e. p in slots.
            for (uint64_t i = 0; i < nb; i++) {
                uint64_t p = bp[i], j;
                for (j = nxt[i]; j < hi; j += p) seg[j - lo] = 0;
                nxt[i] = j;
            }

            uint64_t c = 0;
            for (uint64_t x = 0; x < len; x++) c += seg[x];
            total += c;
        }

        free(seg);
        free(nxt);
    }

    double dt = now() - t0;
    free(bp);

    printf("pi(%llu) = %llu\n", (unsigned long long)N, (unsigned long long)total);
    fprintf(stderr, "sieve time: %.3f s\n", dt);
    return 0;
}

