// Segmented, odd-only sieve of Eratosthenes, multithreaded.
// Build: g++ -O3 -march=native -fopenmp primes.cpp -o primes
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>

static const uint64_t SEG = 256 * 1024; // odd numbers per segment (bytes) -> fits L2

int main(int argc, char** argv) {
    uint64_t N = argc > 1 ? strtoull(argv[1], 0, 10) : 1000000000ULL; // count primes < N
    if (N <= 2) { printf("0\n"); return 0; }
    uint64_t r = (uint64_t)sqrt((double)N) + 1;

    // base primes (odd) up to sqrt(N)
    std::vector<uint8_t> small(r + 1, 1);
    std::vector<uint32_t> bp;
    for (uint64_t i = 3; i <= r; i += 2) {
        if (small[i]) {
            if (i * i <= N) bp.push_back((uint32_t)i);
            for (uint64_t j = i * i; j <= r; j += 2 * i) small[j] = 0;
        }
    }

    // index k represents odd number 2k+1; k from 1 .. (N-1)/2 (numbers < N)
    uint64_t total = (N - 1) / 2 + 1; // indices 0..total-1 cover odd numbers < N
    uint64_t nseg = (total + SEG - 1) / SEG;
    uint64_t count = 1; // the prime 2

    #pragma omp parallel for schedule(dynamic, 1) reduction(+ : count)
    for (int64_t s = 0; s < (int64_t)nseg; s++) {
        thread_local std::vector<uint8_t> buf;
        buf.assign(SEG, 1);
        uint64_t lo = s * SEG, hi = lo + SEG; if (hi > total) hi = total;
        for (uint32_t p : bp) {
            uint64_t start = ((uint64_t)p * p - 1) / 2;
            if (start >= hi) break;
            if (start < lo) start = lo + (((uint64_t)p - (lo - start) % p) % p);
            for (uint64_t j = start - lo; j < hi - lo; j += p) buf[j] = 0;
        }
        uint64_t c = 0;
        for (uint64_t j = 0; j < hi - lo; j++) c += buf[j];
        if (lo == 0) c -= 1; // index 0 is the number 1
        count += c;
    }
    printf("%llu\n", (unsigned long long)count);
    return 0;
}

// Counts primes below N using a multithreaded, odd-only segmented sieve.
// Build: g++ -O3 -march=native -fopenmp primes.cpp -o primes
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <omp.h>

static const uint64_t N = 1000000000ULL;
static const uint32_t SEG = 32768;            // bytes per segment (fits L1); each byte = one odd number
static const uint64_t SPAN = 2ULL * SEG;      // numeric range per segment

int main() {
    uint32_t r = (uint32_t)std::sqrt((double)N) + 1;
    std::vector<uint32_t> primes;             // odd primes up to sqrt(N)
    {
        std::vector<char> c(r + 1, 1);
        for (uint32_t i = 2; (uint64_t)i * i <= r; i++)
            if (c[i]) for (uint32_t j = i * i; j <= r; j += i) c[j] = 0;
        for (uint32_t i = 3; i <= r; i += 2) if (c[i]) primes.push_back(i);
    }
    const size_t np = primes.size();

    uint64_t total = 1;                       // the prime 2 (N > 2)
    int64_t nseg = (int64_t)((N + SPAN - 1) / SPAN);

    #pragma omp parallel reduction(+ : total)
    {
        std::vector<uint8_t> seg(SEG);
        #pragma omp for schedule(dynamic, 4)
        for (int64_t s = 0; s < nseg; s++) {
            uint64_t lo = (uint64_t)s * SPAN;  // segment covers odd numbers lo+1, lo+3, ...
            uint64_t hi = lo + SPAN;           // exclusive
            if (hi > N) hi = N;
            memset(seg.data(), 1, SEG);
            for (size_t k = 0; k < np; k++) {
                uint64_t p = primes[k];
                if (p * p >= hi) break;
                uint64_t start = p * p;
                if (start < lo) {
                    start = ((lo + p - 1) / p) * p;
                    if (!(start & 1)) start += p;
                }
                // index of odd number x in segment: (x - lo - 1) / 2
                for (uint64_t x = start; x < hi; x += 2 * p)
                    seg[(x - lo - 1) >> 1] = 0;
            }
            uint64_t len = (hi - lo) >> 1;     // number of odd slots (hi-lo is even)
            uint64_t cnt = 0;
            for (uint64_t i = 0; i < len; i++) cnt += seg[i];
            if (s == 0) cnt--;                 // exclude 1
            total += cnt;
        }
    }
    printf("%llu\n", (unsigned long long)total);
    return 0;
}

// Count primes below N: odd-only segmented sieve, L1-sized segments, multithreaded.
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <atomic>
#include <thread>

static const uint64_t N = 1000000000ULL;      // count primes < N
static const uint32_t SEG = 32768;            // bytes per segment (one byte per odd number) ~ L1

int main() {
    uint32_t r = (uint32_t)std::sqrt((double)N) + 1;
    // small primes (odd) up to r via simple sieve
    std::vector<char> comp(r + 1, 0);
    std::vector<uint32_t> sp;
    for (uint32_t i = 3; i <= r; i += 2) {
        if (!comp[i]) {
            sp.push_back(i);
            for (uint64_t j = (uint64_t)i * i; j <= r; j += 2 * i) comp[j] = 1;
        }
    }
    // index k represents the odd number 2k+1; k in [1, (N-1)/2]
    const uint64_t K = (N - 1) / 2 + 1;  // indices 0..K-1 cover odds < N (2k+1 <= N-1 for N even)
    const uint64_t nseg = (K + SEG - 1) / SEG;

    unsigned nt = std::thread::hardware_concurrency();
    if (!nt) nt = 1;
    std::atomic<uint64_t> next{0};
    std::vector<uint64_t> counts(nt, 0);

    auto work = [&](unsigned t) {
        std::vector<uint8_t> seg(SEG);
        std::vector<uint32_t> off(sp.size());
        uint64_t cnt = 0;
        for (;;) {
            uint64_t s = next.fetch_add(1);
            if (s >= nseg) break;
            uint64_t lo = s * SEG, hi = lo + SEG;
            if (hi > K) hi = K;
            uint32_t len = (uint32_t)(hi - lo);
            memset(seg.data(), 1, len);
            for (size_t i = 0; i < sp.size(); i++) {
                uint64_t p = sp[i];
                if (p * p >= 2 * hi + 1) break;
                // first index k >= lo with 2k+1 multiple of p and >= p*p
                uint64_t start = (p * p - 1) / 2;
                uint64_t k;
                if (start >= lo) k = start;
                else {
                    // 2k+1 ≡ 0 mod p  => k ≡ (p-1)/2 mod p
                    uint64_t base = (p - 1) / 2;
                    k = lo - ((lo + p - base) % p);
                    // adjust: smallest k>=lo with k%p==base
                    k = lo + ((base + p - lo % p) % p);
                }
                for (; k < hi; k += p) seg[k - lo] = 0;
            }
            if (lo == 0) seg[0] = 0;  // 1 is not prime
            uint64_t c = 0;
            for (uint32_t i = 0; i < len; i++) c += seg[i];
            cnt += c;
        }
        counts[t] = cnt;
    };

    std::vector<std::thread> th;
    for (unsigned t = 1; t < nt; t++) th.emplace_back(work, t);
    work(0);
    for (auto &x : th) x.join();

    uint64_t total = 1;  // the prime 2
    for (auto c : counts) total += c;
    printf("%llu\n", (unsigned long long)total);
}

