The fastest approach is not a sieve. Sieving touches all 10⁹ numbers. A combinatorial prime-counting algorithm (Lucy_Hedgehog's variant of Legendre/Meissel) does about O(n^¾) work, roughly 5 million simple operations for n = 10⁹. It finishes in a few milliseconds, where even a well-tuned segmented sieve takes hundreds.

**primecount.c**
```c
// Counts primes below 1,000,000,000 using Lucy_Hedgehog's O(n^(3/4)) algorithm.
// Build: gcc -O3 -march=native -o primecount primecount.c -lm
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>

static int64_t isqrt64(int64_t n) {
    int64_t r = (int64_t)sqrt((double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;
    return r;
}

int64_t count_primes(int64_t n) {          // number of primes <= n
    if (n < 2) return 0;
    int64_t r = isqrt64(n);
    // small[v] = S(v) for v <= r ; large[i] = S(n / i) for i <= r
    int64_t *small = malloc((r + 1) * sizeof *small);
    int64_t *large = malloc((r + 1) * sizeof *large);
    for (int64_t v = 0; v <= r; v++) small[v] = v - 1;
    for (int64_t i = 1; i <= r; i++) large[i] = n / i - 1;

    for (int64_t p = 2; p <= r; p++) {
        if (small[p] == small[p - 1]) continue;   // p is not prime
        int64_t sp = small[p - 1];                // primes < p
        int64_t p2 = p * p;

        // Update large values S(n/i) for all n/i >= p^2
        int64_t lim = n / p2 < r ? n / p2 : r;
        int64_t i = 1;
        int64_t split = r / p < lim ? r / p : lim;  // for i <= split, i*p <= r
        for (; i <= split; i++)
            large[i] -= large[i * p] - sp;
        for (; i <= lim; i++)
            large[i] -= small[n / (i * p)] - sp;

        // Update small values S(v) for v >= p^2 (descending)
        for (int64_t v = r; v >= p2; v--)
            small[v] -= small[v / p] - sp;
    }
    int64_t result = large[1];
    free(small);
    free(large);
    return result;
}

int main(void) {
    const int64_t N = 1000000000LL;
    printf("%lld\n", (long long)count_primes(N - 1));   // primes strictly below N
    return 0;
}
```

**Build and run:**
```bash
gcc -O3 -march=native -o primecount primecount.c -lm
time ./primecount
```

**Expected output:** `50847534`

**How it works:**
- Let S(v) be the count of integers in [2, v] that survive sieving by all primes processed so far. It starts at S(v) = v − 1.
- For each prime p ≤ √n, every tracked v ≥ p² gets the update S(v) −= S(v/p) − S(p−1). This removes the numbers whose smallest prime factor is p.
- Only about 2√n distinct values of ⌊n/k⌋ ever matter. These are stored in two arrays of size √n ≈ 31,623, so memory use is about 500 KB and stays in L2 cache.
- After all primes up to √n are processed, S(n) equals π(n).

**If you need it faster still**, for example for much larger n such as 10¹⁵ and above: the next step is the Deléglise–Rivat / Gourdon algorithm, roughly O(n^(2/3)/log² n). Kim Walisch's `primecount` library implements it and computes π(10⁹) in well under a millisecond. For 10⁹, the program above is already dominated by process startup time.

The fastest approach is not a sieve. Counting primes doesn't require listing them, so I used the **Lucy_Hedgehog / Legendre-style prime-counting algorithm**. It runs in about O(n^¾ / log n) time and O(√n) memory. For n = 10⁹ that is a few million simple operations, which takes milliseconds. A well-optimized segmented sieve takes hundreds of milliseconds.

```c
// primecount.c — counts primes below 1,000,000,000
// Build: gcc -O3 -march=native -o primecount primecount.c
// Run:   ./primecount        (or ./primecount N for any N < 2^32)
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>

int main(int argc, char **argv) {
    uint32_t n = argc > 1 ? (uint32_t)strtoul(argv[1], NULL, 10) : 1000000000u;
    if (n < 3) { puts("0"); return 0; }
    n -= 1;                       // "below n" -> count primes <= n-1

    uint32_t r = (uint32_t)sqrt((double)n);
    while ((uint64_t)r * r > n) r--;
    while ((uint64_t)(r + 1) * (r + 1) <= n) r++;

    // lo[v] = #numbers in [2..v] surviving the sieve so far, for v <= r
    // hi[i] = same, for v = n / i, i <= r
    uint32_t *lo = malloc((r + 2) * sizeof *lo);
    uint32_t *hi = malloc((r + 2) * sizeof *hi);
    for (uint32_t v = 1; v <= r; v++) {
        lo[v] = v - 1;
        hi[v] = n / v - 1;
    }

    for (uint32_t p = 2; p <= r; p++) {
        if (lo[p] == lo[p - 1]) continue;        // p is not prime
        uint32_t sp = lo[p - 1];                 // primes < p
        uint64_t p2 = (uint64_t)p * p;
        uint32_t lim = (uint32_t)(n / p2 < r ? n / p2 : r);
        uint32_t lim2 = r / p < lim ? r / p : lim;

        // hi[i] -= S(n/(i*p)) - sp
        for (uint32_t i = 1; i <= lim2; i++)       // i*p <= r: value lives in hi
            hi[i] -= hi[i * p] - sp;
        uint32_t np = n / p;
        for (uint32_t i = lim2 + 1; i <= lim; i++) // i*p > r: value lives in lo
            hi[i] -= lo[np / i] - sp;

        // lo[v] -= S(v/p) - sp, for v >= p^2
        for (uint32_t v = r; v >= p2; v--)
            lo[v] -= lo[v / p] - sp;
    }

    printf("%u\n", hi[1]);
    free(lo); free(hi);
    return 0;
}
```

**Output:**
```
50847534
```

**How it works**

- Let S(v) be the count of integers in [2, v] that survive sieving by primes smaller than p. It starts at S(v) = v − 1.
- Sieving by each prime p ≤ √n updates S(v) ← S(v) − (S(v/p) − π(p−1)) for every v ≥ p².
- Only the ~2√n distinct values ⌊n/i⌋ are ever needed. They are stored in two arrays of about 31,623 entries each, roughly 250 KB in total, so everything stays in L2 cache.
- Two details help speed:
  - All arithmetic uses 32-bit integers, which makes division cheaper.
  - The `hi` loop is split at the point where i·p crosses √n, which removes a branch from the hot loop.

**Notes**

- 10⁹ is not prime, so "below 10⁹" and "≤ 10⁹" give the same answer. The known value is π(10⁹) = 50,847,534.
- The program accepts any N < 2³² as an argument, which makes it easy to check, e.g. `./primecount 100` → `25`.
- For much larger N (10¹³ and up), the next step is the Deléglise–Rivat or Gourdon algorithms, as implemented in Kim Walisch's `primecount` library. At 10⁹ this simpler method is already far faster than it takes to launch the process.

