bool ledState = false;

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  if (millis() - lastToggle >= 500) {
    lastToggle += 500;
    ledState = !ledState;
    digitalWrite(LED_PIN, ledState);
  }
  // other code can run here
}
```

