    li {
      display: flex;
      align-items: center;
      gap: 12px;
      background: var(--card);
      padding: 14px 12px;
      border-radius: 14px;
      margin-bottom: 8px;
      box-shadow: 0 1px 3px rgba(0,0,0,.06);
    }
    .check {
      flex-shrink: 0;
      width: 28px; height: 28px;
      border-radius: 50%;
      border: 2px solid var(--accent);
      background: transparent;
      color: white;
      font-size: 1rem;
      display: flex; align-items: center; justify-content: center;
    }
    li.done .check { background: var(--accent); }
    .text { flex: 1; font-size: 1.05rem; word-break: break-word; }
    li.done .text { text-decoration: line-through; color: var(--muted); }
    .delete {
      border: none;
      background: none;
      color: var(--danger);
      font-size: 1.4rem;
      padding: 4px 8px;
    }
    #empty { text-align: center; color: var(--muted); margin-top: 40px; }
    #clearDone {
      display: block;
      margin: 16px auto 0;
      border: none;
      background: none;
      color: var(--danger);
      font-size: 0.95rem;
    }
  </style>
</head>
<body>
  <header>
    <h1>To-Do</h1>
    <div id="count"></div>
  </header>

  <form id="addForm">
    <input id="newTask" type="text" placeholder="Add a task…" autocomplete="off" enterkeyhint="done">
    <button id="addBtn" type="submit" aria-label="Add task">+</button>
  </form>

  <div class="filters">
    <button data-filter="all" class="active">All</button>
    <button data-filter="active">Active</button>
    <button data-filter="done">Done</button>
  </div>

  <ul id="list"></ul>
  <p id="empty">Nothing here yet 🎉</p>
  <button id="clearDone">Clear completed</button>

  <script>
    const STORAGE_KEY = "simple-todo-tasks";
    let tasks = JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");
    let filter = "all";

    const list = document.getElementById("list");
    const input = document.getElementById("newTask");
    const empty = document.getElementById("empty");
    const count = document.getElementById("count");
    const clearDone = document.getElementById("clearDone");

    function save() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
    }

    function render() {
      list.innerHTML = "";
      const visible = tasks.filter(t =>
        filter === "all" ? true : filter === "done" ? t.done : !t.done
      );

      visible.forEach(task => {
        const li = document.createElement("li");
        if (task.done) li.classList.add("done");

        const check = document.createElement("button");
        check.className = "check";
        check.textContent = task.done ? "✓" : "";
        check.setAttribute("aria-label", "Toggle done");
        check.onclick = () => { task.done = !task.done; save(); render(); };

        const text = document.createElement("span");
        text.className = "text";
        text.textContent = task.text;
        // Double-tap to edit
        text.ondblclick = () => {
          const updated = prompt("Edit task", task.text);
          if (updated && updated.trim()) { task.text = updated.trim(); save(); render(); }
        };

        const del = document.createElement("button");
        del.className = "delete";
        del.textContent = "✕";
        del.setAttribute("aria-label", "Delete task");
        del.onclick = () => { tasks = tasks.filter(t => t.id !== task.id); save(); render(); };

        li.append(check, text, del);
        list.appendChild(li);
      });

      const remaining = tasks.filter(t => !t.done).length;
      count.textContent = tasks.length
        ? `${remaining} of ${tasks.length} remaining`
        : "No tasks";
      empty.style.display = visible.length ? "none" : "block";
      clearDone.style.display = tasks.some(t => t.done) ? "block" : "none";
    }

    document.getElementById("addForm").onsubmit = e => {
      e.preventDefault();
      const text = input.value.trim();
      if (!text) return;
      tasks.unshift({ id: Date.now(), text, done: false });
      input.value = "";
      save();
      render();
    };

    document.querySelectorAll(".filters button").forEach(btn => {
      btn.onclick = () => {
        document.querySelector(".filters .active").classList.remove("active");
        btn.classList.add("active");
        filter = btn.dataset.filter;
        render();
      };
    });

    clearDone.onclick = () => {
      if (confirm("Remove all completed tasks?")) {
        tasks = tasks.filter(t => !t.done);
        save();
        render();
      }
    };

    render();
  </script>
</body>
</html>
```

### Features
- Add tasks with the **+** button or your keyboard's Done/Enter key
- Tap the circle to mark a task done, and tap **✕** to delete it
- Double-tap a task to edit it
- Filter by All, Active, or Done, and clear all completed tasks at once
- Saves automatically to your phone's storage
- Switches to dark mode when your phone does

### Getting it on your phone
1. **Host it (easiest):** Upload `todo.html` to a free host such as [GitHub Pages](https://pages.github.com), [Netlify Drop](https://app.netlify.com/drop), or [Tiiny.host](https://tiiny.host). Then open the link on your phone.
2. **Add to your home screen** so it looks and opens like a real app:
   - **iPhone (Safari):** Tap Share, then **Add to Home Screen**.
   - **Android (Chrome):** Tap the ⋮ menu, then **Add to Home screen** (or **Install app**).

Your tasks are stored on that phone's browser only. They won't sync between devices, and clearing your browser data will erase them.

