Here's a complete, self-contained Snake game in a single HTML file. Save it as `snake.html` and open it in any browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake</title>
<style>
  body {
    margin: 0;
    height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: #1a1a2e;
    color: #eee;
    font-family: system-ui, sans-serif;
  }
  #hud { display: flex; gap: 2rem; margin-bottom: 0.75rem; font-size: 1.1rem; }
  canvas {
    background: #16213e;
    border: 3px solid #0f3460;
    border-radius: 6px;
  }
  #msg { margin-top: 0.75rem; opacity: 0.8; }
</style>
</head>
<body>
  <div id="hud">
    <span>Score: <b id="score">0</b></span>
    <span>Best: <b id="best">0</b></span>
  </div>
  <canvas id="game" width="400" height="400"></canvas>
  <div id="msg">Press an arrow key or WASD to start · Space to pause</div>

<script>
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const bestEl = document.getElementById('best');
const msgEl = document.getElementById('msg');

const CELL = 20;
const COLS = canvas.width / CELL;
const ROWS = canvas.height / CELL;

let snake, dir, nextDir, food, score, speed, timer, running, paused, gameOver;
let best = Number(localStorage.getItem('snakeBest') || 0);
bestEl.textContent = best;

function reset() {
  const mid = Math.floor(COLS / 2);
  snake = [{x: mid, y: mid}, {x: mid - 1, y: mid}, {x: mid - 2, y: mid}];
  dir = {x: 1, y: 0};
  nextDir = dir;
  score = 0;
  speed = 120;
  running = false;
  paused = false;
  gameOver = false;
  scoreEl.textContent = 0;
  placeFood();
  draw();
}

function placeFood() {
  const free = [];
  for (let x = 0; x < COLS; x++)
    for (let y = 0; y < ROWS; y++)
      if (!snake.some(s => s.x === x && s.y === y)) free.push({x, y});
  food = free[Math.floor(Math.random() * free.length)];
}

function tick() {
  dir = nextDir;
  const head = {x: snake[0].x + dir.x, y: snake[0].y + dir.y};

  // Wall or self collision (tail is excluded since it moves away this tick)
  const hitWall = head.x < 0 || head.y < 0 || head.x >= COLS || head.y >= ROWS;
  const willGrow = food && head.x === food.x && head.y === food.y;
  const body = willGrow ? snake : snake.slice(0, -1);
  const hitSelf = body.some(s => s.x === head.x && s.y === head.y);

  if (hitWall || hitSelf) return endGame();

  snake.unshift(head);
  if (willGrow) {
    score++;
    scoreEl.textContent = score;
    if (snake.length === COLS * ROWS) return endGame(true);
    placeFood();
    // Speed up gradually
    if (speed > 50) { speed -= 3; restartTimer(); }
  } else {
    snake.pop();
  }
  draw();
}

function endGame(won = false) {
  clearInterval(timer);
  running = false;
  gameOver = true;
  if (score > best) {
    best = score;
    localStorage.setItem('snakeBest', best);
    bestEl.textContent = best;
  }
  draw();
  ctx.fillStyle = 'rgba(0,0,0,0.6)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#fff';
  ctx.textAlign = 'center';
  ctx.font = 'bold 32px system-ui';
  ctx.fillText(won ? 'You Win!' : 'Game Over', canvas.width / 2, canvas.height / 2 - 10);
  ctx.font = '16px system-ui';
  ctx.fillText('Press Enter to play again', canvas.width / 2, canvas.height / 2 + 24);
  msgEl.textContent = `Final score: ${score}`;
}

function restartTimer() {
  clearInterval(timer);
  timer = setInterval(tick, speed);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Food
  if (food) {
    ctx.fillStyle = '#e94560';
    ctx.beginPath();
    ctx.arc(food.x * CELL + CELL / 2, food.y * CELL + CELL / 2, CELL / 2 - 2, 0, Math.PI * 2);
    ctx.fill();
  }

  // Snake
  snake.forEach((s, i) => {
    ctx.fillStyle = i === 0 ? '#4ecca3' : '#3a9e80';
    ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2);
  });

  if (paused) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.font = 'bold 28px system-ui';
    ctx.fillText('Paused', canvas.width / 2, canvas.height / 2);
  }
}

const KEYS = {
  ArrowUp: {x: 0, y: -1}, w: {x: 0, y: -1}, W: {x: 0, y: -1},
  ArrowDown: {x: 0, y: 1}, s: {x: 0, y: 1}, S: {x: 0, y: 1},
  ArrowLeft: {x: -1, y: 0}, a: {x: -1, y: 0}, A: {x: -1, y: 0},
  ArrowRight: {x: 1, y: 0}, d: {x: 1, y: 0}, D: {x: 1, y: 0},
};

document.addEventListener('keydown', e => {
  if (gameOver) {
    if (e.key === 'Enter') {
      reset();
      msgEl.textContent = 'Press an arrow key or WASD to start · Space to pause';
    }
    return;
  }

  if (e.key === ' ' && running) {
    e.preventDefault();
    paused = !paused;
    paused ? clearInterval(timer) : restartTimer();
    draw();
    return;
  }

  const d = KEYS[e.key];
  if (!d || paused) return;
  e.preventDefault();

  // Prevent reversing into yourself
  if (d.x === -dir.x && d.y === -dir.y) return;
  nextDir = d;

  if (!running) {
    running = true;
    msgEl.textContent = 'Space to pause';
    restartTimer();
  }
});

reset();
</script>
</body>
</html>
```

**Features**
- **Controls:** Arrow keys or WASD to move, Space to pause, Enter to restart after game over
- **Gradual speed-up:** the snake gets faster each time it eats
- **High score** saved in `localStorage` so it persists between sessions
- **Fair collision:** moving into the cell your tail is just leaving is allowed, and you can't instantly reverse into yourself
- **Win condition** if you fill the entire board

