  score = 0;
  running = false;
  paused = false;
  gameOver = false;
  scoreEl.textContent = 0;
  placeFood();
  clearTimeout(timer);
  draw();
}

function placeFood() {
  const free = [];
  for (let x = 0; x < GRID; x++)
    for (let y = 0; y < GRID; y++)
      if (!snake.some(s => s.x === x && s.y === y)) free.push({x, y});
  food = free[Math.floor(Math.random() * free.length)];
}

function speed() {
  return Math.max(MIN_SPEED, BASE_SPEED - score * 3);
}

function tick() {
  if (!running || paused) return;

  dir = nextDir;
  const head = {x: snake[0].x + dir.x, y: snake[0].y + dir.y};

  // Wall or self collision (tail is excluded since it moves away this tick)
  const hitsWall = head.x < 0 || head.y < 0 || head.x >= GRID || head.y >= GRID;
  const willEat = food && head.x === food.x && head.y === food.y;
  const body = willEat ? snake : snake.slice(0, -1);
  const hitsSelf = body.some(s => s.x === head.x && s.y === head.y);

  if (hitsWall || hitsSelf) return endGame();

  snake.unshift(head);
  if (willEat) {
    score++;
    scoreEl.textContent = score;
    if (snake.length === GRID * GRID) return endGame(true);
    placeFood();
  } else {
    snake.pop();
  }

  draw();
  timer = setTimeout(tick, speed());
}

function endGame(won = false) {
  running = false;
  gameOver = true;
  if (score > best) {
    best = score;
    localStorage.setItem('snakeBest', best);
    bestEl.textContent = best;
  }
  draw();
  msgEl.textContent = (won ? 'You win! ' : 'Game over! ') + 'Press Enter to restart';
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Food
  if (food) {
    ctx.fillStyle = '#f38ba8';
    ctx.beginPath();
    ctx.arc(food.x * CELL + CELL / 2, food.y * CELL + CELL / 2, CELL / 2.5, 0, Math.PI * 2);
    ctx.fill();
  }

