  snake.forEach((s, i) => {
    ctx.fillStyle = i === 0 ? '#a6e3a1' : '#94e2d5';
    ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2);
  });

  // Overlays
  if (paused || gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#cdd6f4';
    ctx.font = 'bold 32px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText(paused ? 'Paused' : 'Game Over', canvas.width / 2, canvas.height / 2);
  }
}

const KEYS = {
  ArrowUp: {x: 0, y: -1}, w: {x: 0, y: -1}, W: {x: 0, y: -1},
  ArrowDown: {x: 0, y: 1}, s: {x: 0, y: 1}, S: {x: 0, y: 1},
  ArrowLeft: {x: -1, y: 0}, a: {x: -1, y: 0}, A: {x: -1, y: 0},
  ArrowRight: {x: 1, y: 0}, d: {x: 1, y: 0}, D: {x: 1, y: 0},
};

document.addEventListener('keydown', e => {
  if (e.key === 'Enter' && gameOver) {
    reset();
    msgEl.textContent = 'Press an arrow key or WASD to start · Space to pause';
    return;
  }

  if (e.key === ' ' && running) {
    e.preventDefault();
    paused = !paused;
    draw();
    if (!paused) timer = setTimeout(tick, speed());
    return;
  }

  const d = KEYS[e.key];
  if (!d || gameOver) return;
  e.preventDefault();

  // Prevent reversing directly into yourself
  if (d.x === -dir.x && d.y === -dir.y) return;
  nextDir = d;

  if (!running) {
    running = true;
    msgEl.textContent = 'Space to pause';
    timer = setTimeout(tick, speed());
  }
});

reset();
</script>
</body>
</html>
```

**Features**
- **Controls:** Arrow keys or WASD to move, Space to pause, Enter to restart after a game over.
- **Speed ramps up** as your score increases (capped so it stays playable).
- **High score** is saved in `localStorage` so it persists between sessions.
- **Fair collisions:** you can't instantly reverse into yourself, and moving into the cell your tail is leaving is allowed.
- **Food never spawns on the snake**, and filling the whole board counts as a win.

