    <button id="clear" class="clear">Clear completed</button>
  </div>

  <script>
    const KEY = "todos-v1";
    let todos = JSON.parse(localStorage.getItem(KEY) || "[]");
    let filter = "all";

    const $ = (id) => document.getElementById(id);
    const save = () => localStorage.setItem(KEY, JSON.stringify(todos));

    function render() {
      const list = $("list");
      list.innerHTML = "";
      const shown = todos.filter(t =>
        filter === "all" ? true : filter === "done" ? t.done : !t.done);

      if (!shown.length) {
        list.innerHTML = `<li class="empty" style="border:none;background:none;justify-content:center">
          ${todos.length ? "Nothing here" : "No tasks yet 🎉"}</li>`;
      }

      shown.forEach(t => {
        const li = document.createElement("li");
        if (t.done) li.className = "done";

        const cb = document.createElement("input");
        cb.type = "checkbox";
        cb.checked = t.done;
        cb.onchange = () => { t.done = cb.checked; save(); render(); };

        const span = document.createElement("span");
        span.textContent = t.text;
        span.ondblclick = () => edit(t);

        const del = document.createElement("button");
        del.className = "del";
        del.textContent = "✕";
        del.setAttribute("aria-label", "Delete");
        del.onclick = () => { todos = todos.filter(x => x.id !== t.id); save(); render(); };

        li.append(cb, span, del);
        list.appendChild(li);
      });

      const left = todos.filter(t => !t.done).length;
      $("count").textContent = `${left} task${left === 1 ? "" : "s"} left`;
      $("clear").style.display = todos.some(t => t.done) ? "block" : "none";
    }

    function edit(t) {
      const text = prompt("Edit task", t.text);
      if (text && text.trim()) { t.text = text.trim(); save(); render(); }
    }

    $("form").onsubmit = (e) => {
      e.preventDefault();
      const text = $("input").value.trim();
      if (!text) return;
      todos.unshift({ id: Date.now(), text, done: false });
      $("input").value = "";
      save(); render();
    };

    document.querySelectorAll(".filters button").forEach(btn => {
      btn.onclick = () => {
        document.querySelector(".filters .active").classList.remove("active");
        btn.classList.add("active");
        filter = btn.dataset.filter;
        render();
      };
    });

    $("clear").onclick = () => {
      if (confirm("Remove all completed tasks?")) {
        todos = todos.filter(t => !t.done); save(); render();
      }
    };

    render();
  </script>
</body>
</html>
```

## Features
- Add tasks with the **+** button or the keyboard's Done key
- Tap the checkbox to mark a task done
- **✕** deletes a task. Double-tap a task to edit it
- Filter by All, Active or Done, and clear all completed tasks at once
- Tasks are saved on your phone and stay there after you close the page
- Dark mode turns on automatically if your phone uses it

## Getting it onto your phone
1. Save the code above as `index.html`.
2. Put the file online. The easiest way is to drag it onto [app.netlify.com/drop](https://app.netlify.com/drop) (free, no setup), or use GitHub Pages.
3. Open the link on your phone:
   - **iPhone (Safari):** tap Share, then **Add to Home Screen**
   - **Android (Chrome):** tap ⋮, then **Add to Home screen**

It will then open full-screen from your home screen like a normal app.

> Note: Your tasks are stored only on that phone, in that browser. If you clear your browser data, the tasks are deleted too.

