Here's a complete, self-contained Snake game in a single HTML file. Save it as `snake.html` and open it in any browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake</title>
<style>
  body {
    margin: 0;
    height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: #1a1a2e;
    color: #eee;
    font-family: system-ui, sans-serif;
  }
  #hud {
    display: flex;
    gap: 2rem;
    margin-bottom: 0.75rem;
    font-size: 1.2rem;
  }
  canvas {
    background: #16213e;
    border: 3px solid #0f3460;
    border-radius: 6px;
  }
  #msg {
    margin-top: 0.75rem;
    opacity: 0.8;
  }
</style>
</head>
<body>
  <div id="hud">
    <span>Score: <b id="score">0</b></span>
    <span>Best: <b id="best">0</b></span>
  </div>
  <canvas id="game" width="400" height="400"></canvas>
  <div id="msg">Press an arrow key or WASD to start · Space to pause</div>

<script>
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const bestEl = document.getElementById('best');
const msgEl = document.getElementById('msg');

const CELL = 20;
const COLS = canvas.width / CELL;
const ROWS = canvas.height / CELL;

let snake, dir, nextDir, food, score, speed, timer, running, paused, gameOver;
let best = Number(localStorage.getItem('snakeBest') || 0);
bestEl.textContent = best;

function reset() {
  snake = [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }];
  dir = { x: 1, y: 0 };
  nextDir = dir;
  score = 0;
  speed = 120;
  running = false;
  paused = false;
  gameOver = false;
  scoreEl.textContent = score;
  placeFood();
  draw();
}

function placeFood() {
  do {
    food = {
      x: Math.floor(Math.random() * COLS),
      y: Math.floor(Math.random() * ROWS),
    };
  } while (snake.some(s => s.x === food.x && s.y === food.y));
}

function start() {
  running = true;
  msgEl.textContent = 'Space to pause';
  loop();
}

function loop() {
  clearTimeout(timer);
  timer = setTimeout(() => {
    if (!paused) step();
    if (running) loop();
  }, speed);
}

function step() {
  dir = nextDir;
  const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

  // Collision with walls or self (tail is allowed since it will move)
  const hitWall = head.x < 0 || head.y < 0 || head.x >= COLS || head.y >= ROWS;
  const hitSelf = snake.slice(0, -1).some(s => s.x === head.x && s.y === head.y);
  if (hitWall || hitSelf) return end();

  snake.unshift(head);

  if (head.x === food.x && head.y === food.y) {
    score++;
    scoreEl.textContent = score;
    speed = Math.max(50, speed - 3); // gradually speed up
    placeFood();
  } else {
    snake.pop();
  }
  draw();
}

function end() {
  running = false;
  gameOver = true;
  clearTimeout(timer);
  if (score > best) {
    best = score;
    localStorage.setItem('snakeBest', best);
    bestEl.textContent = best;
  }
  draw();
  msgEl.textContent = 'Game over! Press Enter or any arrow key to restart';
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Food
  ctx.fillStyle = '#e94560';
  ctx.beginPath();
  ctx.arc(food.x * CELL + CELL / 2, food.y * CELL + CELL / 2, CELL / 2 - 2, 0, Math.PI * 2);
  ctx.fill();

  // Snake
  snake.forEach((s, i) => {
    ctx.fillStyle = i === 0 ? '#7CFC00' : '#4caf50';
    ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2);
  });

  if (gameOver || paused) {
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 32px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText(gameOver ? 'GAME OVER' : 'PAUSED', canvas.width / 2, canvas.height / 2);
  }
}

const KEYS = {
  ArrowUp: { x: 0, y: -1 }, w: { x: 0, y: -1 }, W: { x: 0, y: -1 },
  ArrowDown: { x: 0, y: 1 }, s: { x: 0, y: 1 }, S: { x: 0, y: 1 },
  ArrowLeft: { x: -1, y: 0 }, a: { x: -1, y: 0 }, A: { x: -1, y: 0 },
  ArrowRight: { x: 1, y: 0 }, d: { x: 1, y: 0 }, D: { x: 1, y: 0 },
};

document.addEventListener('keydown', e => {
  if (gameOver && (e.key === 'Enter' || KEYS[e.key])) {
    reset();
    if (KEYS[e.key]) e.preventDefault();
    return;
  }

  if (e.key === ' ') {
    e.preventDefault();
    if (running) {
      paused = !paused;
      msgEl.textContent = paused ? 'Paused · Space to resume' : 'Space to pause';
      draw();
    }
    return;
  }

  const d = KEYS[e.key];
  if (!d) return;
  e.preventDefault();

  // Prevent reversing directly into yourself
  if (d.x === -dir.x && d.y === -dir.y) return;
  nextDir = d;

  if (!running && !gameOver) start();
});

reset();
</script>
</body>
</html>
```

**Features**
- **Controls:** Arrow keys or WASD to move, Space to pause or resume, and Enter (or any arrow key) to restart after a game over.
- **Speed:** The snake gets a little faster with each piece of food you eat.
- **Collisions:** Hitting a wall or your own body ends the game.
- **Best score:** Your high score is saved in the browser's `localStorage`, so it persists between sessions.
- **No instant death:** The game ignores a key press that would reverse the snake straight into itself.

**Easy tweaks**
- `CELL` sets the size of each grid square. Change it, or the canvas `width`/`height`, to resize the board.
- `speed = 120` is the starting tick in milliseconds. Lower numbers are faster.
- `Math.max(50, ...)` caps the top speed.

If you'd like a different version, I can make one that runs in the terminal with Python and `curses`, or uses Pygame.

