#!/usr/bin/env python3
"""Count word frequencies in a text file and print the 10 most common."""

import re
import sys
from collections import Counter


def top_words(path, n=10):
    counts = Counter()
    with open(path, encoding="utf-8") as f:
        for line in f:
            counts.update(re.findall(r"[a-z0-9']+", line.lower()))
    return counts.most_common(n)


def main():
    if len(sys.argv) != 2:
        print(f"usage: {sys.argv[0]} FILE", file=sys.stderr)
        sys.exit(1)
    for word, count in top_words(sys.argv[1]):
        print(f"{count:>7}  {word}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Count word frequencies in a text file and print the most common ones."""

import argparse
import re
import sys
from collections import Counter

WORD_RE = re.compile(r"[a-z0-9]+(?:'[a-z0-9]+)*")


def count_words(path):
    counts = Counter()
    with open(path, encoding="utf-8", errors="replace") as f:
        for line in f:
            counts.update(WORD_RE.findall(line.lower()))
    return counts


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("file", help="path to the text file")
    parser.add_argument("-n", type=int, default=10, help="number of words to show (default: 10)")
    args = parser.parse_args()

    try:
        counts = count_words(args.file)
    except OSError as e:
        sys.exit(f"error: {e}")

    for word, count in counts.most_common(args.n):
        print(f"{count:>8}  {word}")


if __name__ == "__main__":
    main()

