def monthly_totals(path):
    df = pd.read_csv(path, parse_dates=["date"])
    df["month"] = df["date"].dt.to_period("M")
    return (
        df.groupby(["month", "region"], as_index=False)["amount"]
        .sum()
        .sort_values(["month", "region"])
    )


