#!/usr/bin/env python3
"""Total sales per month per region.

Usage: python3 monthly_sales.py sales.csv [output.csv]

Expects a CSV with a header row containing: date, region, amount.
"""
import csv
import sys
from collections import defaultdict
from datetime import datetime
from decimal import Decimal, InvalidOperation

DATE_FORMATS = ("%Y-%m-%d", "%Y/%m/%d", "%m/%d/%Y", "%d/%m/%Y", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S")


def parse_month(value):
    value = value.strip()
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(value, fmt).strftime("%Y-%m")
        except ValueError:
            pass
    raise ValueError(f"unrecognized date: {value!r}")


def main(path, out_path=None):
    totals = defaultdict(Decimal)
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        reader.fieldnames = [name.strip().lower() for name in reader.fieldnames]
        for line_no, row in enumerate(reader, start=2):
            try:
                month = parse_month(row["date"])
                amount = Decimal(row["amount"].strip().replace(",", "").replace("$", ""))
            except (ValueError, InvalidOperation) as e:
                print(f"skipping line {line_no}: {e}", file=sys.stderr)
                continue
            totals[(month, row["region"].strip())] += amount

    out = open(out_path, "w", newline="") if out_path else sys.stdout
    writer = csv.writer(out)
    writer.writerow(["month", "region", "total_sales"])
    for (month, region), total in sorted(totals.items()):
        writer.writerow([month, region, f"{total:.2f}"])
    if out_path:
        out.close()


if __name__ == "__main__":
    if len(sys.argv) not in (2, 3):
        sys.exit(__doc__)
    main(*sys.argv[1:])

