// Count primes below N (default 1,000,000,000) using the Lucy_Hedgehog
// variant of the Legendre/Meissel prime-counting method: O(N^(3/4)) time,
// O(N^(1/2)) memory. Runs in milliseconds for N = 1e9; no sieve needed.
//
// Build: cc -O2 -march=native -o primecount primecount.c -lm
// Run:   ./primecount [N]
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int main(int argc, char **argv) {
    int64_t limit = argc > 1 ? atoll(argv[1]) : 1000000000LL;
    if (limit < 3) { puts("0"); return 0; }
    int64_t n = limit - 1; // "below limit" == "<= limit-1"

    int64_t r = (int64_t)sqrtl((long double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;

    // lo[v] = S(v) for v <= r;  hi[i] = S(n / i) for i <= r.
    // S(v) starts as v - 1 (all integers 2..v) and is sieved down to pi(v).
    int64_t *lo = malloc((r + 1) * sizeof *lo);
    int64_t *hi = malloc((r + 1) * sizeof *hi);
    if (!lo || !hi) { perror("malloc"); return 1; }
    lo[0] = 0;
    for (int64_t i = 1; i <= r; i++) {
        lo[i] = i - 1;
        hi[i] = n / i - 1;
    }

    for (int64_t p = 2; p <= r; p++) {
        if (lo[p] == lo[p - 1]) continue; // p is not prime
        int64_t sp = lo[p - 1];           // number of primes < p
        int64_t p2 = p * p;

        // Large values v = n/i with v >= p^2, i.e. i <= n/p^2.
        int64_t lim = n / p2;
        if (lim > r) lim = r;
        int64_t i = 1;
        int64_t direct = r / p < lim ? r / p : lim; // i*p <= r -> use hi[i*p]
        for (; i <= direct; i++)
            hi[i] -= hi[i * p] - sp;
        for (; i <= lim; i++)
            hi[i] -= lo[n / (i * p)] - sp;

        // Small values v in [p^2, r], descending so lo[v/p] is still old.
        for (int64_t v = r; v >= p2; v--)
            lo[v] -= lo[v / p] - sp;
    }

    printf("%lld\n", (long long)hi[1]);
    free(lo);
    free(hi);
    return 0;
}

