// Count primes below 1,000,000,000.
// Segmented, odd-only Sieve of Eratosthenes, parallelised with OpenMP.
//
// Build: gcc -O3 -march=native -fopenmp primes.c -o primes -lm
// Run:   ./primes            (expected output: 50847534)

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>

#define N   1000000000ULL      // count primes < N
#define SEG (1u << 16)         // odd numbers per segment (64 KB of bytes, fits L2)

int main(void) {
    // Base primes up to sqrt(N).
    uint32_t lim = (uint32_t)sqrt((double)N) + 1;
    uint8_t *comp = calloc(lim + 1, 1);
    uint32_t *primes = malloc(sizeof(uint32_t) * (lim / 2 + 1));
    int np = 0;
    for (uint32_t i = 3; i <= lim; i += 2) {
        if (comp[i]) continue;
        primes[np++] = i;
        for (uint64_t j = (uint64_t)i * i; j <= lim; j += 2 * i) comp[j] = 1;
    }
    free(comp);

    // Index k represents the odd number 2k+1; odd numbers below N are k in [0, N/2).
    const uint64_t K = N / 2;
    const uint64_t nseg = (K + SEG - 1) / SEG;
    uint64_t total = 1; // the prime 2

    #pragma omp parallel reduction(+:total)
    {
        uint8_t *seg = aligned_alloc(64, SEG);

        #pragma omp for schedule(dynamic, 16)
        for (uint64_t s = 0; s < nseg; s++) {
            uint64_t lo = s * SEG;
            uint64_t hi = lo + SEG < K ? lo + SEG : K;
            uint32_t len = (uint32_t)(hi - lo);
            uint64_t low = 2 * lo + 1, high = 2 * hi - 1; // numbers covered

            memset(seg, 1, len);
            if (lo == 0) seg[0] = 0; // 1 is not prime

            for (int i = 0; i < np; i++) {
                uint64_t p = primes[i];
                uint64_t pp = p * p;
                if (pp > high) break;
                uint64_t m;
                if (pp >= low) {
                    m = pp;
                } else {
                    m = (low + p - 1) / p * p;
                    if (!(m & 1)) m += p;
                }
                uint32_t k = (uint32_t)((m - 1) / 2 - lo);
                uint32_t step = (uint32_t)p;
                // Unrolled striking loop.
                uint32_t step4 = step * 4;
                while (k + 3 * step < len) {
                    seg[k] = 0;
                    seg[k + step] = 0;
                    seg[k + 2 * step] = 0;
                    seg[k + 3 * step] = 0;
                    k += step4;
                }
                for (; k < len; k += step) seg[k] = 0;
            }

            uint32_t c = 0;
            for (uint32_t j = 0; j < len; j++) c += seg[j]; // vectorised by -O3
            total += c;
        }

        free(seg);
    }

    printf("%llu\n", (unsigned long long)total);
    free(primes);
    return 0;
}

