// Count primes below 1,000,000,000 using Lucy_Hedgehog's prime-counting
// algorithm (a Legendre/Meissel-style combinatorial method).
// Runs in O(n^(3/4)) time and O(sqrt n) memory: ~ a few milliseconds,
// versus ~0.5-1 s for even a well-tuned segmented sieve.
//
// Build: gcc -O3 -march=native -o primecount primecount.c -lm
// Run:   ./primecount            (default limit 1e9)
//        ./primecount 10000000000

#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

static int64_t isqrt64(int64_t n) {
    int64_t r = (int64_t)sqrt((double)n);
    while (r * r > n) r--;
    while ((r + 1) * (r + 1) <= n) r++;
    return r;
}

// Number of primes p with p <= n.
static int64_t prime_pi(int64_t n) {
    if (n < 2) return 0;
    int64_t r = isqrt64(n);

    // lo[v] = count of "survivors" in [2, v] for small v <= r
    // hi[i] = count of "survivors" in [2, n/i] for i <= r
    int64_t *lo = malloc((r + 2) * sizeof *lo);
    int64_t *hi = malloc((r + 2) * sizeof *hi);
    if (!lo || !hi) { perror("malloc"); exit(1); }

    for (int64_t v = 0; v <= r; v++) lo[v] = v - 1;
    lo[0] = 0;
    for (int64_t i = 1; i <= r; i++) hi[i] = n / i - 1;

    for (int64_t p = 2; p <= r; p++) {
        if (lo[p] == lo[p - 1]) continue;  // p is not prime
        int64_t sp = lo[p - 1];            // primes below p
        int64_t p2 = p * p;

        // Large values n/i >= p^2.
        int64_t lim = n / p2;
        if (lim > r) lim = r;
        int64_t i = 1;
        int64_t split = r / p;  // i*p <= r  <=>  i <= r/p
        if (split > lim) split = lim;
        for (; i <= split; i++) hi[i] -= hi[i * p] - sp;
        for (; i <= lim; i++) hi[i] -= lo[n / (i * p)] - sp;

        // Small values v >= p^2.
        for (int64_t v = r; v >= p2; v--) lo[v] -= lo[v / p] - sp;
    }

    int64_t result = hi[1];
    free(lo);
    free(hi);
    return result;
}

int main(int argc, char **argv) {
    int64_t limit = argc > 1 ? strtoll(argv[1], NULL, 10) : 1000000000LL;

    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    int64_t count = prime_pi(limit - 1);  // primes strictly below limit
    clock_gettime(CLOCK_MONOTONIC, &t1);

    double ms = (t1.tv_sec - t0.tv_sec) * 1e3 + (t1.tv_nsec - t0.tv_nsec) / 1e6;
    printf("primes below %lld: %lld\n", (long long)limit, (long long)count);
    fprintf(stderr, "time: %.3f ms\n", ms);
    return 0;
}

