// Blink an LED once per second (500 ms on, 500 ms off).
// Targets Arduino-compatible boards (Uno, Nano, Mega, ESP32, etc.).

const uint8_t LED_PIN = LED_BUILTIN;          // On-board LED; change to any digital pin
const unsigned long HALF_PERIOD_MS = 500;     // 500 ms on + 500 ms off = 1 blink/second

unsigned long lastToggle = 0;
bool ledOn = false;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
}

void loop() {
  // Non-blocking timing: loop() stays free for other work.
  // Unsigned subtraction handles millis() rollover after ~49 days.
  unsigned long now = millis();
  if (now - lastToggle >= HALF_PERIOD_MS) {
    lastToggle += HALF_PERIOD_MS;             // Step by a fixed interval so timing doesn't drift
    ledOn = !ledOn;
    digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
  }
}

