// Blink the on-board LED once per second (500 ms on, 500 ms off).
// Target: Arduino Uno/Nano/Mega and most Arduino-compatible boards.

const uint8_t LED_PIN = LED_BUILTIN;          // Pin 13 on the Uno
const unsigned long HALF_PERIOD_MS = 500;     // 500 on + 500 off = 1 s

unsigned long lastToggle = 0;
bool ledOn = false;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
}

void loop() {
  // Use millis() instead of delay() so the loop doesn't block other work.
  unsigned long now = millis();
  if (now - lastToggle >= HALF_PERIOD_MS) {   // Unsigned subtraction still works when millis() wraps
    lastToggle += HALF_PERIOD_MS;             // Add to the last toggle time, not to now, so timing doesn't drift
    ledOn = !ledOn;
    digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
  }
}

